'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api), ['isPowerOfTen']);
const { isPowerOfTen } = api;

for (const value of [1, 10, 100, 1000, 1000000000, 1000000000000000]) {
  assert.strictEqual(isPowerOfTen(value), true, String(value));
}
for (const value of [0, -1, -10, -1000, 2, 9, 11, 99, 101, 1001, 1.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER, 10000000000000000, '10', 10n, null, undefined, true, {}, []]) {
  assert.strictEqual(isPowerOfTen(value), false, String(value));
}

